contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(am <= amount);
        require(address(this).balance >= amount);
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint recBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == recBefore - am && address(c).balance == cBalBefore - am);
    }
    fallback() external payable {}
}

