pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, uint256 am) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(am <= amount);
        vm.assume(address(this).balance >= amount);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 recBefore;
        try c.balances(address(this)) returns (uint256 __r) { recBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        try c.Collect(am) {} catch { return; }
        assertTrue(c.balances(address(this)) == recBefore - am && address(c).balance == cBalBefore - am);
    }

    function testFuzz_run(uint256 amount, uint256 am) public {
        _run(amount, am);
    }

    fallback() external payable {}
}
